package auth

// Exported — accessible from other packages
type Service struct {
    repo Repository
}

// Unexported — package-private
type tokenClaims struct {
    userID int
    exp    time.Time
}

func NewService(repo Repository) *Service {
    return &Service{repo: repo}
}

