// init function — runs before main
package config

var Settings AppConfig

func init() {
    // Load config from environment
    Settings = AppConfig{
        Port:    getEnv("PORT", "8080"),
        DBHost:  getEnv("DB_HOST", "localhost"),
    }
}

func getEnv(key, fallback string) string {
    if val := os.Getenv(key); val != "" {
        return val
    }
    return fallback
}
